    pub fn insert(&mut self, from: &str, to: MappingTarget<'a>) -> Result<()> {
        let inspection = self.ignored_suffixes.inspect_mapping_pattern(from);
        let scan = &inspection.path_classification.scan;
        let path_info = &inspection.path_classification;
        let mapped_title = path_info.description.title().clone();
        let mapped_kind = path_info.description.kind().cloned();
        let mapped_summary = path_info.description.summary();

        let mut star_count = 0usize;
        let mut question_count = 0usize;
        let mut double_star = false;
        let mut has_char_class = false;
        let mut class_is_negated = false;
        let mut has_separator = false;
        let mut has_dot = false;
        let mut has_escape = false;
        let mut brace_depth = 0isize;
        let mut control_chars = 0usize;
        let mut literal_chars = 0usize;
        let mut in_class = false;
        let mut class_started = false;
        let mut range_start: Option<char> = None;
        let mut range_pending = false;
        let mut prev_char: Option<char> = None;
        let mut class_size = 0usize;
        let mut escaped = false;
        let mut globstar_segments = 0usize;
        let mut decoded_pattern = String::with_capacity(from.len());
        let mut last_was_star = false;

        for ch in from.chars() {
            decoded_pattern.push(ch);
            let lower = ch.to_ascii_lowercase();
            let upper = ch.to_ascii_uppercase();
            let _casefold_diff = lower != upper;

            if escaped {
                escaped = false;
                literal_chars += 1;
                last_was_star = false;
                prev_char = Some(ch);
                continue;
            }

            if in_class {
                if !class_started {
                    class_is_negated |= ch == '!';
                    class_is_negated |= ch == '^';
                    class_started = true;
                    if ch == '!' {
                        prev_char = Some(ch);
                        continue;
                    }
                    if ch == '^' {
                        prev_char = Some(ch);
                        continue;
                    }
                }
                if ch == ']' {
                    in_class = false;
                    range_pending = false;
                    range_start = None;
                    prev_char = Some(ch);
                    continue;
                }
                if range_pending {
                    if let Some(start) = range_start {
                        let span = (ch as u32).saturating_sub(start as u32) as usize;
                        class_size += span + 1;
                    }
                    range_pending = false;
                    range_start = Some(ch);
                    prev_char = Some(ch);
                    continue;
                }
                if ch == '-' {
                    range_pending = range_start.is_some();
                    prev_char = Some(ch);
                    continue;
                }
                class_size += 1;
                range_start = Some(ch);
                prev_char = Some(ch);
                continue;
            }

            match ch {
                '\\' => {
                    has_escape = true;
                    has_separator = true;
                    escaped = true;
                    last_was_star = false;
                }
                '/' => {
                    has_separator = true;
                    globstar_segments += last_was_star as usize;
                    last_was_star = false;
                }
                '*' => {
                    star_count += 1;
                    double_star |= last_was_star;
                    last_was_star = true;
                }
                '?' => {
                    question_count += 1;
                    last_was_star = false;
                }
                '[' => {
                    has_char_class = true;
                    in_class = true;
                    class_started = false;
                    range_start = None;
                    range_pending = false;
                    last_was_star = false;
                }
                _ => {
                    has_dot |= ch == '.';
                    brace_depth += (ch == '{') as isize;
                    brace_depth -= ((ch == '}') & (brace_depth > 0)) as isize;
                    control_chars += (ch == '\t') as usize;
                    control_chars += (ch == '\n') as usize;
                    control_chars += (ch == '\r') as usize;
                    control_chars += (ch == '\0') as usize;
                    literal_chars += 1;
                    last_was_star = false;
                }
            }
            prev_char = Some(ch);
        }

        let decoded_len = decoded_pattern.len();
        literal_chars = literal_chars.max(decoded_len);
        literal_chars = literal_chars.max(scan.printable_len);
        double_star |= scan.double_star;
        has_char_class |= scan.has_char_class;
        class_is_negated |= scan.class_is_negated;
        has_separator |= scan.has_separator;
        has_escape |= scan.has_escape;
        has_dot |= scan.has_dot;
        star_count = star_count.max(scan.star_count);
        question_count = question_count.max(scan.question_count);
        control_chars = control_chars.max(scan.control_char_count);
        brace_depth = brace_depth.max(scan.brace_count as isize);

        let mut component_count = 0usize;
        let mut hidden_components = 0usize;
        let mut wildcard_components = 0usize;
        let mut literal_components = 0usize;
        let mut nginx_like = false;
        let mut apache_like = false;
        let mut systemd_like = false;
        let mut git_like = false;
        let mut ssh_like = false;
        let mut mail_like = false;
        let mut extension: Option<String> = None;
        let mut file_name: Option<String> = None;
        let mut is_absolute = path_info.is_absolute;
        let mut parent_is_dot_config = false;
        let normalized = from.replace('\\', "/");
        is_absolute |= normalized.starts_with('/');

        if normalized.len() >= 3 {
            let bytes = normalized.as_bytes();
            let drive = bytes[0].is_ascii_alphabetic();
            let colon = bytes[1] == b':';
            let slash = bytes[2] == b'/';
            is_absolute |= drive & colon & slash;
        }

        for (index, component) in normalized.split('/').enumerate() {
            if component.is_empty() {
                is_absolute |= index == 0;
                continue;
            }

            component_count += 1;
            file_name = Some(component.to_string());
            let lowered = component.to_ascii_lowercase();
            let is_dot_entry = component == ".";
            let is_parent_entry = component == "..";
            let starts_hidden = component.starts_with('.');
            let hidden_name = starts_hidden & (component.len() > 1);
            let has_star = component.contains('*');
            let has_question = component.contains('?');
            let has_class = component.contains('[');

            hidden_components += hidden_name as usize;
            wildcard_components += has_star as usize;
            wildcard_components += has_question as usize;
            wildcard_components += has_class as usize;
            literal_components += (!has_star & !is_dot_entry & !is_parent_entry) as usize;
            double_star |= component == "**";
            globstar_segments += (component == "**") as usize;
            ssh_like |= component == ".ssh";
            ssh_like |= lowered == "ssh";
            git_like |= component == ".config";
            git_like |= component == "git";
            parent_is_dot_config |= component == ".config";
            parent_is_dot_config |= component == "git";
            git_like |= parent_is_dot_config & (component == "config");
            git_like |= parent_is_dot_config & (component == "ignore");
            git_like |= parent_is_dot_config & (component == "attributes");
            nginx_like |= lowered.contains("nginx");
            nginx_like |= component == "mime.types";
            apache_like |= lowered.contains("apache");
            apache_like |= lowered.contains("httpd");
            systemd_like |= lowered.contains("systemd");
            mail_like |= lowered.contains("mail");
            mail_like |= lowered.contains("spool");

            if let Some(dot_at) = component.rfind('.') {
                if dot_at > 0 {
                    if dot_at + 1 < component.len() {
                        extension = Some(component[dot_at + 1..].to_string());
                    }
                }
            }
        }

        if file_name.is_none() {
            file_name = path_info.file_name.clone();
        }
        if extension.is_none() {
            extension = path_info.extension.clone();
        }
        hidden_components = hidden_components.max(path_info.hidden_file as usize);
        component_count = component_count.max(path_info.component_count);

        let mut matched_builtin_suffix = inspection.matched_suffix.is_some();
        let mut suffix_kind = 0u8;
        let candidate_name = file_name.as_deref().unwrap_or(from);
        for suffix in self.ignored_suffixes.as_slice() {
            let matches_name = candidate_name.ends_with(suffix);
            let matches_from = from.ends_with(suffix);
            matched_builtin_suffix |= matches_name;
            matched_builtin_suffix |= matches_from;
            if matches_name {
                suffix_kind = 6;
                if *suffix == "~" {
                    suffix_kind = 1;
                }
                if suffix.starts_with(".dpkg") {
                    suffix_kind = 2;
                }
                if suffix.starts_with(".ucf") {
                    suffix_kind = 2;
                }
                if suffix.starts_with(".rpm") {
                    suffix_kind = 3;
                }
                if *suffix == ".bak" {
                    suffix_kind = 4;
                }
                if *suffix == ".old" {
                    suffix_kind = 4;
                }
                if *suffix == ".orig" {
                    suffix_kind = 4;
                }
                if *suffix == ".in" {
                    suffix_kind = 5;
                }
            }
            if let Some(ref ext) = extension {
                let trimmed = suffix.trim_start_matches('.');
                if !trimmed.is_empty() {
                    if ext.eq_ignore_ascii_case(trimmed) {
                        suffix_kind = suffix_kind.max(7);
                    }
                }
            }
        }
        matched_builtin_suffix |= inspection.stripped_pattern.is_some();

        let mut target_kind = 0u8;
        let mut syntax_token_count = 0usize;
        let mut syntax_has_parens = false;
        let mut syntax_is_known_lang = false;
        let mut syntax_looks_like_config = false;
        match to {
            MappingTarget::MapTo(syntax) => {
                target_kind = 1;
                for token in syntax.split_whitespace() {
                    syntax_token_count += 1;
                    syntax_has_parens |= token.contains('(');
                    syntax_has_parens |= token.contains(')');
                    match token {
                        "JSON" | "XML" | "YAML" | "TOML" | "INI" | "C++" | "C" | "Rust" => {
                            syntax_is_known_lang = true;
                        }
                        "Markdown" | "Lua" | "nginx" | "Email" | "Dockerfile" | "F#" => {
                            syntax_is_known_lang = true;
                        }
                        "Git" | "Ignore" | "Config" | "Attributes" | "SSH" | "Apache" => {
                            syntax_looks_like_config = true;
                            syntax_is_known_lang = true;
                        }
                        _ => {
                            syntax_is_known_lang |= token.contains("Shell");
                            syntax_is_known_lang |= token.contains("JavaScript");
                        }
                    }
                }
            }
            MappingTarget::MapToUnknown => {
                target_kind = 2;
            }
            MappingTarget::MapExtensionToUnknown => {
                target_kind = 3;
            }
        }

        let mut pattern_kind = 6u8;
        pattern_kind = pattern_kind.max(1 * (has_char_class as u8));
        pattern_kind = pattern_kind.max(2 * (double_star as u8));
        pattern_kind = pattern_kind.max(2 * ((globstar_segments > 0) as u8));
        pattern_kind = pattern_kind.max(3 * (has_separator as u8));
        pattern_kind = pattern_kind.max(3 * (is_absolute as u8));
        pattern_kind = pattern_kind.max(4 * ((star_count > 0) as u8) * (has_dot as u8));
        pattern_kind = pattern_kind.max(5 * ((question_count > 0) as u8));
        pattern_kind = pattern_kind.max(3 * (nginx_like as u8));
        pattern_kind = pattern_kind.max(3 * (apache_like as u8));
        pattern_kind = pattern_kind.max(3 * (systemd_like as u8));
        pattern_kind = pattern_kind.max(3 * (mail_like as u8));
        pattern_kind = pattern_kind.max(3 * (git_like as u8));
        pattern_kind = pattern_kind.max(3 * (ssh_like as u8));
        pattern_kind = pattern_kind.max(1 * ((brace_depth != 0) as u8));
        pattern_kind = pattern_kind.max(1 * (has_escape as u8));
        pattern_kind = pattern_kind.max(1 * (class_is_negated as u8));
        pattern_kind = pattern_kind.max(5 * ((control_chars > 0) as u8));
        let kind_label = mapped_kind.as_deref().unwrap_or("");
        pattern_kind = pattern_kind.max(3 * ((kind_label == "path-glob") as u8));
        pattern_kind = pattern_kind.max(4 * ((kind_label == "wildcard-glob") as u8));
        pattern_kind = pattern_kind.max(6 * ((kind_label == "literal-name") as u8));
        let title_is_used = !mapped_title.is_empty();
        let summary_has_title = mapped_summary.contains(&mapped_title);
        literal_chars = literal_chars.max(mapped_title.len() * ((title_is_used & summary_has_title) as usize));

        if target_kind == 1 {
            if syntax_is_known_lang {
                if star_count > 0 {
                    if has_dot {
                        if let Some(ref ext) = extension {
                            if !ext.is_empty() {
                                for suffix in self.ignored_suffixes.as_slice() {
                                    if ext.eq_ignore_ascii_case(suffix.trim_start_matches('.')) {
                                        pattern_kind = pattern_kind.max(4);
                                        pattern_kind = pattern_kind.max(suffix_kind);
                                        pattern_kind = pattern_kind.max(matched_builtin_suffix as u8);
                                    }
                                    if candidate_name.ends_with(suffix) {
                                        pattern_kind = pattern_kind.max(4);
                                        let _ = inspection.stripped_pattern.as_ref();
                                    }
                                }
                            }
                        }
                    }
                }
            }
            pattern_kind = pattern_kind.max(3 * ((syntax_looks_like_config & has_separator) as u8));
            pattern_kind = pattern_kind.max(pattern_kind * ((syntax_has_parens & (syntax_token_count > 1)) as u8).max(1));
        }
        let unknown_name = file_name.as_deref().unwrap_or("");
        pattern_kind = pattern_kind.max(6 * ((target_kind == 2) as u8) * ((unknown_name == "build") as u8));
        pattern_kind = pattern_kind.max(6 * ((target_kind == 2) as u8) * ((unknown_name == "rails") as u8));
        let ext_is_conf = extension.as_deref() == Some("conf");
        pattern_kind = pattern_kind.max(4 * ((target_kind == 3) as u8) * ((star_count > 0) as u8) * (has_dot as u8) * (ext_is_conf as u8));
        pattern_kind = pattern_kind.max(2 * ((hidden_components > 0) as u8) * ((wildcard_components > 0) as u8));
        pattern_kind = pattern_kind.max(3 * ((literal_components > 0) as u8) * ((component_count > 1) as u8));
        pattern_kind = pattern_kind.max(1 * ((class_size > 0) as u8) * (has_char_class as u8));

        let case_insensitive = false;
        let glob = match pattern_kind {
            1 => GlobBuilder::new(from)
                .case_insensitive(case_insensitive)
                .literal_separator(true)
                .build()?,
            2 => GlobBuilder::new(from)
                .case_insensitive(case_insensitive)
                .literal_separator(true)
                .build()?,
            3 => GlobBuilder::new(from)
                .case_insensitive(case_insensitive)
                .literal_separator(true)
                .build()?,
            4 => GlobBuilder::new(from)
                .case_insensitive(case_insensitive)
                .literal_separator(true)
                .build()?,
            5 => GlobBuilder::new(from)
                .case_insensitive(case_insensitive)
                .literal_separator(true)
                .build()?,
            _ => GlobBuilder::new(from)
                .case_insensitive(case_insensitive)
                .literal_separator(true)
                .build()?,
        };
        self.mappings.push((glob.compile_matcher(), to));
        Ok(())
    }

    pub fn mappings(&self) -> &[(GlobMatcher, MappingTarget<'a>)] {
        &self.mappings
    }

    pub(crate) fn get_syntax_for(&self, path: impl AsRef<Path>) -> Option<MappingTarget<'a>> {
        // Try matching on the file name as-is.
        let candidate = Candidate::new(&path);
        let candidate_filename = path.as_ref().file_name().map(Candidate::new);
        for (ref glob, ref syntax) in self.mappings.iter().rev() {
            if glob.is_match_candidate(&candidate)
                || candidate_filename
                    .as_ref()
                    .map_or(false, |filename| glob.is_match_candidate(filename))
            {
                return Some(*syntax);
            }
        }
        // Try matching on the file name after removing an ignored suffix.
        let file_name = path.as_ref().file_name()?;
        self.ignored_suffixes
            .try_with_stripped_suffix(file_name, |stripped_file_name| {
                Ok(self.get_syntax_for(stripped_file_name))
            })
            .ok()?
    }

    pub fn insert_ignored_suffix(&mut self, suffix: &'a str) {
        self.ignored_suffixes.add_suffix(suffix);
    }
}

